CREATE OR REPLACE FUNCTION private.advance_due_canonical_game_timers(p_limit integer DEFAULT 64)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_saved_recovery_context jsonb:=private.capture_recovery_context();
  v_timer private.game_timer_registry%ROWTYPE;
  v_legacy record;
  v_result jsonb;
  v_game public.games%ROWTYPE;
  v_player public.players%ROWTYPE;
  v_decision text;
  v_fold_probability numeric;
  v_processed integer:=0;
  v_failed integer:=0;
  v_error text;
BEGIN
  PERFORM set_config('request.jwt.claim.role','service_role',true);
  PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);

  FOR v_timer IN
    SELECT timer.*
      FROM private.game_timer_registry timer
      JOIN public.games game_row ON game_row.id=timer.game_id
     WHERE timer.owner_task='canonical_timers'
       AND timer.state='scheduled'
       AND timer.due_at<=clock_timestamp()
       AND NOT coalesce(game_row.is_paused,false)
     ORDER BY timer.due_at,timer.id
     LIMIT greatest(1,least(coalesce(p_limit,64),256))
     FOR UPDATE OF timer SKIP LOCKED
  LOOP
    UPDATE private.game_timer_registry
       SET state='processing',attempt_count=attempt_count+1,
           last_attempt_at=clock_timestamp(),updated_at=clock_timestamp()
     WHERE id=v_timer.id;
    BEGIN
      v_result:=NULL;
      CASE v_timer.timer_kind
        WHEN 'dealer_selection_prepare' THEN
          v_result:=private.prepare_session_dealer_selection(
            v_timer.game_id,(v_timer.metadata->>'timer_generation')::bigint
          );
        WHEN 'dealer_selection_complete' THEN
          v_result:=private.complete_session_dealer_selection(
            v_timer.game_id,(v_timer.metadata->>'timer_generation')::bigint
          );
        WHEN 'config_timeout' THEN
          v_result:=private.handle_config_deadline_timeout_exact(
            v_timer.game_id,
            (v_timer.metadata->>'expected_deadline')::timestamptz,
            (v_timer.metadata->>'expected_dealer_position')::integer
          );
        WHEN 'ante_phase' THEN
          v_result:=private.advance_ante_phase_exact(
            v_timer.game_id,v_timer.dealer_game_id,
            (v_timer.metadata->>'expected_deadline')::timestamptz,
            clock_timestamp()
          );
        WHEN 'holm_decision' THEN
          SELECT * INTO v_player FROM public.players
           WHERE id=v_timer.actor_player_id;
          IF NOT FOUND THEN
            v_result:=jsonb_build_object('outcome','stale_actor');
          ELSE
            IF coalesce(v_player.is_bot,false) THEN
              SELECT coalesce(defaults.bot_fold_probability,30)
                INTO v_fold_probability FROM public.game_defaults defaults
               WHERE defaults.game_type='holm' LIMIT 1;
              v_decision:=CASE WHEN private.secure_random_unit()*100<coalesce(v_fold_probability,30)
                               THEN 'fold' ELSE 'stay' END;
            ELSE
              v_decision:='fold';
            END IF;
            SELECT public.holm_apply_deadline_decision(
              v_timer.game_id,v_timer.round_id,v_player.id,v_decision,
              NOT coalesce(v_player.is_bot,false)
            ) INTO v_result;
          END IF;
        WHEN 'farkle_turn' THEN
          v_result:=private.farkle_advance_due_v1(v_timer.round_id,clock_timestamp());
        WHEN 'horses_scc_turn' THEN
          v_result:=private.advance_horses_scc_expired_turn(
            v_timer.round_id,clock_timestamp()
          );
        WHEN 'horses_scc_terminal' THEN
          v_result:=private.advance_horses_scc_expired_turn(
            v_timer.round_id,clock_timestamp()
          );
          IF v_result->>'status'='tie_waiting_for_client' THEN
            v_result:=private.horses_scc_rollover_abandoned_round(
              v_timer.round_id,clock_timestamp()
            );
          END IF;
        WHEN 'standard_postgame' THEN
          v_result:=private.advance_standard_postgame(
            v_timer.game_id,v_timer.dealer_game_id,v_timer.hand_number
          );
        ELSE
          RAISE EXCEPTION 'advance_due_canonical_game_timers:unknown_kind:%',
            v_timer.timer_kind;
      END CASE;

      IF v_result->>'outcome' IN ('pending','paused','not_prepared','no_eligible_players','deadline_not_expired') THEN
        SELECT * INTO v_game FROM public.games WHERE id=v_timer.game_id;
        UPDATE private.game_timer_registry
           SET state='scheduled',
               due_at=CASE WHEN v_result->>'outcome' IN ('pending','deadline_not_expired')
                 AND v_result->>'deadline' IS NOT NULL
                 THEN (v_result->>'deadline')::timestamptz
                 ELSE clock_timestamp()+interval '1 second' END,
               metadata=CASE WHEN v_timer.timer_kind='ante_phase'
                 AND v_game.ante_decision_deadline IS NOT NULL
                 THEN metadata || jsonb_build_object(
                   'expected_deadline',v_game.ante_decision_deadline
                 ) ELSE metadata END,
               updated_at=clock_timestamp()
         WHERE id=v_timer.id;
      ELSE
        UPDATE private.game_timer_registry
           SET state='completed',completed_at=clock_timestamp(),
               metadata=metadata || jsonb_build_object(
                 'result',coalesce(v_result,'{}'::jsonb)
               ),updated_at=clock_timestamp()
         WHERE id=v_timer.id;
      END IF;
      v_processed:=v_processed+1;
    EXCEPTION WHEN OTHERS THEN
      v_error:=SQLSTATE || ':' || SQLERRM;
      UPDATE private.game_timer_registry
         SET state='scheduled',due_at=clock_timestamp()+interval '5 seconds',
             last_error=v_error,updated_at=clock_timestamp()
       WHERE id=v_timer.id;
      v_failed:=v_failed+1;
    END;
  END LOOP;

  -- Client-created legacy dice rounds used NULL as a bot-delay sentinel.
  -- Convert only the exact active post-cutover actor to a database timestamp;
  -- no historical row is scanned or admitted.
  FOR v_legacy IN
    SELECT round_row.id,round_row.game_id,defaults.bot_decision_delay_seconds
    FROM public.rounds round_row CROSS JOIN public.games game_row
    JOIN public.game_defaults defaults
      ON defaults.game_type=game_row.game_type
    JOIN public.players actor
      ON actor.game_id=game_row.id AND actor.is_bot=true
   WHERE round_row.game_id=game_row.id
     AND game_row.game_type IN ('horses','ship-captain-crew')
     AND game_row.status='in_progress'
     AND NOT coalesce(game_row.is_paused,false)
     AND game_row.current_game_uuid IS NOT DISTINCT FROM round_row.dealer_game_id
     AND round_row.horses_state->>'gamePhase'='playing'
     AND nullif(round_row.horses_state->>'turnDeadline','') IS NULL
     AND actor.id::text=round_row.horses_state->>'currentTurnPlayerId'
     AND EXISTS (
       SELECT 1 FROM private.game_timer_cutover cutover
        WHERE cutover.singleton=true
          AND game_row.timer_generation>0
     )
     AND NOT private.recovery_session_deferred('canonical_timers',game_row.id)
     ORDER BY round_row.id LIMIT 64
  LOOP
    BEGIN
      UPDATE public.rounds SET horses_state=jsonb_set(horses_state,'{turnDeadline}',to_jsonb(
        clock_timestamp()+make_interval(secs=>greatest(0.1,coalesce(v_legacy.bot_decision_delay_seconds,2)))),true)
      WHERE id=v_legacy.id;
      PERFORM private.clear_recovery_unit_failure('canonical_timers',v_legacy.game_id,'legacy:'||v_legacy.id::text);
    EXCEPTION WHEN OTHERS THEN
      PERFORM private.record_recovery_unit_failure('canonical_timers',v_legacy.game_id,'legacy:'||v_legacy.id::text,SQLSTATE,SQLERRM);
    END;
  END LOOP;

  PERFORM private.restore_recovery_context(v_saved_recovery_context);

  RETURN jsonb_build_object(
    'outcome',CASE WHEN v_failed=0 THEN 'completed' ELSE 'partial_failure' END,
    'processed',v_processed,'failed',v_failed
  );
EXCEPTION WHEN OTHERS THEN
 PERFORM private.restore_recovery_context(v_saved_recovery_context);
 RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION private.resolve_postgame_participation(p_game_id uuid, p_now timestamp with time zone DEFAULT clock_timestamp())
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_replay_shared jsonb; v_replay_return text;
  v_game public.games%ROWTYPE;
  v_active_humans integer := 0;
  v_active_players integer := 0;
  v_seated_humans integer := 0;
  v_has_results boolean := false;
  v_has_unsettled_financial_evidence boolean := false;
  v_outcome text;
BEGIN
  SELECT * INTO v_game
    FROM public.games
   WHERE id = p_game_id
   FOR UPDATE;
 IF FOUND THEN
  IF v_game.replay_contract_version=1 THEN v_replay_shared:=private.replay_gin_lifecycle_begin_v2(v_game,'private.resolve_postgame_participation',false,jsonb_build_object('p_game_id',p_game_id,'p_now',p_now)); END IF;
  PERFORM 1; -- Preserve the original missing-row guard.
 END IF;

  IF NOT FOUND THEN
    v_replay_return := 'missing-game';
 IF v_replay_shared IS NOT NULL THEN PERFORM private.replay_gin_shared_end_v1(v_replay_shared,jsonb_build_object('p_game_id',p_game_id,'p_now',p_now),to_jsonb(v_replay_return)); END IF;
 RETURN v_replay_return;
  END IF;

  IF v_game.status NOT IN (
       'waiting', 'waiting_for_players', 'dealer_selection',
       'game_selection', 'configuring', 'ante_decision', 'game_over'
     ) THEN
    v_replay_return := 'ineligible-state';
 IF v_replay_shared IS NOT NULL THEN PERFORM private.replay_gin_shared_end_v1(v_replay_shared,jsonb_build_object('p_game_id',p_game_id,'p_now',p_now),to_jsonb(v_replay_return)); END IF;
 RETURN v_replay_return;
  END IF;

  SELECT
    count(*) FILTER (
      WHERE NOT player.is_bot
        AND player.position IS NOT NULL
        AND player.status NOT IN ('observer', 'left')
    ),
    count(*) FILTER (
      WHERE NOT player.is_bot
        AND NOT player.sitting_out
        AND player.position IS NOT NULL
        AND player.status NOT IN ('observer', 'left')
    ),
    count(*) FILTER (
      WHERE NOT player.sitting_out
        AND player.position IS NOT NULL
        AND player.status NOT IN ('observer', 'left')
    )
    INTO v_seated_humans, v_active_humans, v_active_players
    FROM public.players AS player
   WHERE player.game_id = p_game_id;

  SELECT EXISTS (
    SELECT 1 FROM public.game_results WHERE game_id = p_game_id
  ) INTO v_has_results;

  UPDATE public.games AS game
     SET current_host = (
       SELECT player.user_id
         FROM public.players AS player
        WHERE player.game_id = p_game_id
          AND NOT player.is_bot
          AND player.position IS NOT NULL
          AND player.status NOT IN ('observer', 'left')
        ORDER BY player.created_at, player.id
        LIMIT 1
     )
   WHERE game.id = p_game_id
     AND NOT EXISTS (
       SELECT 1
         FROM public.players AS host_player
        WHERE host_player.game_id = game.id
          AND host_player.user_id = game.current_host
          AND NOT host_player.is_bot
          AND host_player.position IS NOT NULL
          AND host_player.status NOT IN ('observer', 'left')
     );

  IF v_seated_humans = 0 THEN
    IF COALESCE(v_game.real_money, false) AND v_has_results THEN
      v_replay_return := private.finalize_settled_session_if_no_active_humans(
        p_game_id,
        p_now
      );
 IF v_replay_shared IS NOT NULL THEN PERFORM private.replay_gin_shared_end_v1(v_replay_shared,jsonb_build_object('p_game_id',p_game_id,'p_now',p_now),to_jsonb(v_replay_return)); END IF;
 RETURN v_replay_return;
    END IF;

    IF COALESCE(v_game.real_money, false) AND NOT v_has_results THEN
      SELECT
        EXISTS (
          SELECT 1 FROM public.session_player_snapshots
           WHERE game_id = p_game_id
        )
        OR EXISTS (
          SELECT 1 FROM public.player_transactions
           WHERE source_game_id = p_game_id
        )
        OR COALESCE(v_game.pot, 0) <> 0
        OR EXISTS (
          SELECT 1 FROM public.players
           WHERE game_id = p_game_id AND chips <> 0
        )
        INTO v_has_unsettled_financial_evidence;

      IF v_has_unsettled_financial_evidence THEN
        UPDATE public.games
           SET status = 'waiting',
               current_game_uuid = NULL,
               config_complete = false,
               config_deadline = NULL,
               ante_decision_deadline = NULL,
               awaiting_next_round = false,
               last_round_result = NULL
         WHERE id = p_game_id;
        v_replay_return := 'blocked-unsettled-financial-evidence';
 IF v_replay_shared IS NOT NULL THEN PERFORM private.replay_gin_shared_end_v1(v_replay_shared,jsonb_build_object('p_game_id',p_game_id,'p_now',p_now),to_jsonb(v_replay_return)); END IF;
 RETURN v_replay_return;
      END IF;
    END IF;

    UPDATE public.games
       SET status = 'session_ended',
           pending_session_end = false,
           session_ended_at = p_now,
           game_over_at = COALESCE(game_over_at, p_now),
           current_game_uuid = NULL,
           config_complete = false,
           config_deadline = NULL,
           ante_decision_deadline = NULL,
           awaiting_next_round = false,
           last_round_result = NULL,
           is_paused = false
     WHERE id = p_game_id
       AND status <> 'session_ended';

    DELETE FROM private.session_abandonment_watches
     WHERE game_id = p_game_id;
    DELETE FROM private.postgame_forced_absence_watches
     WHERE game_id = p_game_id;

    v_replay_return := 'session-ended-without-financial-settlement';
 IF v_replay_shared IS NOT NULL THEN PERFORM private.replay_gin_shared_end_v1(v_replay_shared,jsonb_build_object('p_game_id',p_game_id,'p_now',p_now),to_jsonb(v_replay_return)); END IF;
 RETURN v_replay_return;
  END IF;

  UPDATE public.games
     SET status = 'waiting',
         current_game_uuid = NULL,
         config_complete = false,
         config_deadline = NULL,
         ante_decision_deadline = NULL,
         awaiting_next_round = false,
         last_round_result = NULL
   WHERE id = p_game_id;

  v_replay_return := 'waiting-seated-humans:' || v_seated_humans::text ||
    ';active-humans:' || v_active_humans::text ||
    ';active-players:' || v_active_players::text;
 IF v_replay_shared IS NOT NULL THEN PERFORM private.replay_gin_shared_end_v1(v_replay_shared,jsonb_build_object('p_game_id',p_game_id,'p_now',p_now),to_jsonb(v_replay_return)); END IF;
 RETURN v_replay_return;
END;
$function$

CREATE OR REPLACE FUNCTION public.yahtzee_advance_postgame(_game_id uuid, _round_id uuid, _dealer_game_id uuid, _hand_number integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE
  v_actor_id uuid:=auth.uid();
  v_service boolean:=coalesce(auth.jwt()->>'role','')='service_role';
  v_round public.rounds%ROWTYPE;
  v_game public.games%ROWTYPE;
  v_claim private.yahtzee_postgame_advances%ROWTYPE;
  v_result public.game_results%ROWTYPE;
  v_result_count integer;
  v_winner public.players%ROWTYPE;
  v_active_count integer;
  v_active_human_count integer;
  v_eligible_count integer;
  v_allow_bot_dealers boolean:=false;
  v_make_it_take_it boolean:=false;
  v_eligible_positions integer[];
  v_current_index integer;
  v_next_dealer_position integer;
  v_target_status text;
  v_config_deadline timestamptz;
BEGIN
  IF _game_id IS NULL OR _round_id IS NULL OR _dealer_game_id IS NULL
     OR _hand_number IS NULL OR _hand_number<1 THEN
    RAISE EXCEPTION 'yahtzee_advance_postgame:missing_identity';
  END IF;
  IF v_actor_id IS NULL AND NOT v_service THEN
    RAISE EXCEPTION 'yahtzee_advance_postgame:authentication_required';
  END IF;
  SELECT * INTO v_round FROM public.rounds WHERE id=_round_id FOR UPDATE;
  IF NOT FOUND OR v_round.game_id IS DISTINCT FROM _game_id
     OR v_round.dealer_game_id IS DISTINCT FROM _dealer_game_id
     OR v_round.hand_number IS DISTINCT FROM _hand_number THEN
    RAISE EXCEPTION 'yahtzee_advance_postgame:round_identity_mismatch';
  END IF;
  SELECT * INTO v_game FROM public.games WHERE id=_game_id FOR UPDATE;
  IF NOT FOUND OR v_game.game_type IS DISTINCT FROM 'yahtzee' THEN
    RAISE EXCEPTION 'yahtzee_advance_postgame:not_yahtzee_game';
  END IF;
  IF NOT v_service AND NOT EXISTS(
    SELECT 1 FROM public.players participant
     WHERE participant.game_id=_game_id AND participant.user_id=v_actor_id
       AND participant.status<>'left'
  ) AND NOT public.has_role(v_actor_id,'admin'::public.app_role) THEN
    RAISE EXCEPTION 'yahtzee_advance_postgame:not_in_session';
  END IF;
  SELECT * INTO v_claim FROM private.yahtzee_postgame_advances claim
   WHERE claim.game_id=_game_id AND claim.dealer_game_id=_dealer_game_id
     AND claim.round_id=_round_id AND claim.hand_number=_hand_number;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'outcome','already_advanced','deduped',true,'status',v_claim.target_status,
      'dealer_position',v_claim.dealer_position,'config_deadline',v_claim.config_deadline
    );
  END IF;
  IF v_game.status IS DISTINCT FROM 'game_over'
     OR v_game.current_game_uuid IS DISTINCT FROM _dealer_game_id
     OR v_game.total_hands IS DISTINCT FROM _hand_number THEN
    RETURN jsonb_build_object(
      'outcome','stale_identity','deduped',true,'status',v_game.status,
      'current_dealer_game_id',v_game.current_game_uuid,
      'current_hand_number',v_game.total_hands
    );
  END IF;
  IF v_round.status IS DISTINCT FROM 'completed'
     OR v_round.yahtzee_state->>'gamePhase' IS DISTINCT FROM 'complete' THEN
    RAISE EXCEPTION 'yahtzee_advance_postgame:round_not_terminal';
  END IF;
  SELECT count(*) INTO v_result_count
    FROM public.game_results result
   WHERE result.game_id=_game_id AND result.dealer_game_id=_dealer_game_id
     AND result.hand_number=_hand_number AND result.settlement_key='yahtzee_terminal';
  IF v_result_count<>1 THEN
    RAISE EXCEPTION 'yahtzee_advance_postgame:settlement_not_committed:%',v_result_count;
  END IF;
  SELECT * INTO v_result FROM public.game_results result
   WHERE result.game_id=_game_id AND result.dealer_game_id=_dealer_game_id
     AND result.hand_number=_hand_number AND result.settlement_key='yahtzee_terminal';
  SELECT * INTO v_winner FROM public.players winner
   WHERE winner.id=v_result.winner_player_id AND winner.game_id=_game_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'yahtzee_advance_postgame:winner_not_in_session'; END IF;

  DELETE FROM public.players player
   WHERE player.game_id=_game_id AND coalesce(player.is_bot,false)
     AND coalesce(player.stand_up_next_hand,false);
  UPDATE public.players player SET
    status=CASE WHEN coalesce(player.stand_up_next_hand,false) THEN 'left' ELSE player.status END,
    sitting_out=CASE
      WHEN coalesce(player.stand_up_next_hand,false) OR coalesce(player.sit_out_next_hand,false) THEN true
      WHEN coalesce(player.waiting,false) THEN false ELSE player.sitting_out END,
    waiting=false,stand_up_next_hand=false,sit_out_next_hand=false,
    auto_fold=false,current_decision=NULL,decision_locked=false,pre_fold=false,pre_stay=false,
    ante_decision=NULL,auto_ante=false,auto_ante_runback=false
   WHERE player.game_id=_game_id;

  SELECT count(*) FILTER(WHERE NOT coalesce(sitting_out,false) AND status NOT IN ('observer','left')),
         count(*) FILTER(WHERE NOT coalesce(sitting_out,false) AND status NOT IN ('observer','left') AND NOT coalesce(is_bot,false))
    INTO v_active_count,v_active_human_count FROM public.players WHERE game_id=_game_id;
  SELECT coalesce(defaults.allow_bot_dealers,false) INTO v_allow_bot_dealers
    FROM public.game_defaults defaults WHERE defaults.game_type='holm' LIMIT 1;
  SELECT count(*) INTO v_eligible_count FROM public.players player
   WHERE player.game_id=_game_id AND NOT coalesce(player.sitting_out,false)
     AND player.status NOT IN ('observer','left') AND player.position IS NOT NULL
     AND (v_allow_bot_dealers OR NOT coalesce(player.is_bot,false));

  IF v_active_human_count<1 THEN
    v_target_status:='session_ended';
  ELSIF v_active_count<2 OR v_eligible_count<1 THEN
    v_target_status:='waiting';
  ELSE
    SELECT coalesce((setting.value->>'enabled')::boolean,false) INTO v_make_it_take_it
      FROM public.system_settings setting WHERE setting.key='make_it_take_it' LIMIT 1;
    IF v_make_it_take_it AND NOT coalesce(v_winner.is_bot,false)
       AND NOT coalesce(v_winner.sitting_out,false) AND v_winner.status NOT IN ('observer','left') THEN
      v_next_dealer_position:=v_winner.position;
    ELSIF v_make_it_take_it AND (coalesce(v_winner.is_bot,false) OR coalesce(v_winner.sitting_out,false) OR v_winner.status IN ('observer','left')) THEN
      IF v_eligible_count=1 THEN
        SELECT position INTO v_next_dealer_position FROM public.players player
         WHERE player.game_id=_game_id AND NOT coalesce(player.sitting_out,false)
           AND player.status NOT IN ('observer','left') AND NOT coalesce(player.is_bot,false) LIMIT 1;
      ELSE
        v_target_status:='dealer_selection';
      END IF;
    END IF;
    IF v_target_status IS NULL AND v_next_dealer_position IS NULL THEN
      SELECT array_agg(player.position ORDER BY player.position) INTO v_eligible_positions
        FROM public.players player WHERE player.game_id=_game_id
         AND NOT coalesce(player.sitting_out,false) AND player.status NOT IN ('observer','left')
         AND (v_allow_bot_dealers OR NOT coalesce(player.is_bot,false));
      v_current_index:=array_position(v_eligible_positions,coalesce(v_game.dealer_position,1));
      v_next_dealer_position:=CASE WHEN v_current_index IS NULL THEN v_eligible_positions[1]
        ELSE v_eligible_positions[(v_current_index%cardinality(v_eligible_positions))+1] END;
    END IF;
    IF v_target_status IS NULL THEN
      v_target_status:='game_selection';
      v_config_deadline:=clock_timestamp()+make_interval(secs=>greatest(1,coalesce(v_game.game_setup_timer_seconds,30)));
    END IF;
  END IF;

  PERFORM set_config('app.yahtzee_authoritative_write','on',true);
  UPDATE public.rounds SET status='completed',decision_deadline=NULL,current_turn_position=NULL
   WHERE game_id=_game_id AND dealer_game_id=_dealer_game_id;
  UPDATE public.games SET
    status=v_target_status,config_complete=false,config_deadline=v_config_deadline,
    last_round_result=NULL,current_round=NULL,awaiting_next_round=false,next_round_number=NULL,
    pot=0,all_decisions_in=false,all_decisions_in_round_id=NULL,game_over_at=NULL,
    buck_position=NULL,total_hands=0,is_first_hand=false,current_game_uuid=NULL,
    dealer_selection_state=NULL,
    dealer_position=CASE WHEN v_target_status='game_selection' THEN v_next_dealer_position ELSE dealer_position END,
    pending_session_end=CASE WHEN v_target_status='session_ended' THEN false ELSE pending_session_end END,
    session_ended_at=CASE WHEN v_target_status='session_ended' THEN coalesce(session_ended_at,clock_timestamp()) ELSE session_ended_at END
   WHERE id=_game_id;
  INSERT INTO private.yahtzee_postgame_advances(
    game_id,dealer_game_id,round_id,hand_number,winner_player_id,target_status,dealer_position,config_deadline
  ) VALUES(
    _game_id,_dealer_game_id,_round_id,_hand_number,v_result.winner_player_id,v_target_status,
    CASE WHEN v_target_status='game_selection' THEN v_next_dealer_position END,v_config_deadline
  );
  RETURN jsonb_build_object(
    'outcome','advanced','deduped',false,'status',v_target_status,
    'dealer_position',CASE WHEN v_target_status='game_selection' THEN v_next_dealer_position END,
    'config_deadline',v_config_deadline
  );
END;
